"""Shared rendering primitives for slide generation.

Provides the canvas dimensions, font directory, gradient factory,
centered-text drawing helper, and provenance-file writer used by all
slide decks.
"""

import pathlib

from PIL import Image, ImageDraw

W, H = 2560, 1440
FONT_DIR = pathlib.Path("C:/Windows/Fonts")


def make_gradient(top_rgb, bot_rgb):
    """Return a W×H image filled with a vertical linear gradient."""
    img = Image.new("RGB", (W, H))
    draw = ImageDraw.Draw(img)
    for y in range(H):
        t = y / (H - 1)
        r = int(top_rgb[0] + (bot_rgb[0] - top_rgb[0]) * t)
        g = int(top_rgb[1] + (bot_rgb[1] - top_rgb[1]) * t)
        b = int(top_rgb[2] + (bot_rgb[2] - top_rgb[2]) * t)
        draw.line([(0, y), (W, y)], fill=(r, g, b))
    return img


def draw_centered_lines(img, lines, gap_after):
    """Draw a vertical stack of text lines, centered on the image.

    lines     — list of (text, font, color_rgb)
    gap_after — list of pixel gaps after each line (last entry unused)
    """
    draw = ImageDraw.Draw(img)
    bboxes = [draw.textbbox((0, 0), text, font=font) for text, font, _ in lines]
    line_heights = [bb[3] - bb[1] for bb in bboxes]
    n = len(lines)
    advance_to_last = sum(line_heights[i] + gap_after[i] for i in range(n - 1))
    # Start Y so the visual ink block is centered
    y = H // 2 - (bboxes[0][1] + advance_to_last + bboxes[-1][3]) // 2
    for i, ((text, font, color), bb) in enumerate(zip(lines, bboxes)):
        text_w = bb[2] - bb[0]
        x = (W - text_w) // 2 - bb[0]
        draw.text((x, y), text, font=font, fill=color)
        y += line_heights[i] + gap_after[i]


def write_provenance(
    dest: pathlib.Path,
    deck_name: str,
    slide_name: str,
    command: str | None = None,
) -> None:
    """Write a provenance .md file into a sibling *-provenance directory.

    For example, if dest is in ``misc/.../img/``, the provenance file is
    written to ``misc/.../img-provenance/``.
    """
    prov_dir = dest.parent.with_name(dest.parent.name + "-provenance")
    prov_dir.mkdir(parents=True, exist_ok=True)
    prov = prov_dir / (dest.stem + "-provenance.md")
    if command is None:
        command = f"MAM-basics/py/main_slide_generator.py render-slides --deck {deck_name} {slide_name}"
    elif command.startswith("py/"):
        command = f"MAM-basics/{command}"
    prov.write_text(
        f"<!-- Auto-generated by {command}. Do not edit by hand. -->\n\n"
        f"Generated by `{command}`.\n",
        encoding="utf-8",
    )
